  ready: '<i class="fa-solid fa-circle-check" aria-hidden="true"></i>',
  loading: '<i class="fa-solid fa-spinner" aria-hidden="true"></i>',
  success: '<i class="fa-solid fa-circle-check" aria-hidden="true"></i>',
