function isLicenseActive() {
  try {
    return localStorage.getItem(LS_LICENSE_OK) === "1";
  } catch {
    return false;
  }
}

function setLicenseVerified(ok, key) {
  try {
    if (ok) {
      localStorage.setItem(LS_LICENSE_OK, "1");
      if (key) localStorage.setItem(LS_LICENSE_KEY, key);
    } else {
      localStorage.removeItem(LS_LICENSE_OK);
      localStorage.removeItem(LS_LICENSE_KEY);
      localStorage.removeItem(LS_LICENSE_ACTIVATION);
      localStorage.removeItem(LS_LICENSE_SNAPSHOT);
    }
  } catch (e) {
    console.error(e);
  }
}

function saveLicenseSnapshotFromApi(data) {
  if (!data) {
    try {
      localStorage.removeItem(LS_LICENSE_SNAPSHOT);
    } catch {
      /* ignore */
    }
    return;
  }
  const snap = {
    display_key: data.display_key || "",
    expires_at: data.expires_at != null ? data.expires_at : null,
    usage: data.usage,
    limit_usage: data.limit_usage,
    last_validated_at: data.last_validated_at != null ? data.last_validated_at : null,
    validations: data.validations,
    status: data.status || "",
  };
  try {
    localStorage.setItem(LS_LICENSE_SNAPSHOT, JSON.stringify(snap));
  } catch (e) {
    console.warn(e);
  }
}

function getLicenseSnapshot() {
  try {
    const raw = localStorage.getItem(LS_LICENSE_SNAPSHOT);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function formatPolarDateTime(iso) {
  if (iso == null || iso === "") return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso);
  try {
    return new Intl.DateTimeFormat("mn-MN", {
      dateStyle: "medium",
      timeStyle: "short",
    }).format(d);
  } catch {
    return d.toLocaleString();
  }
}

function formatUsageLine(usage, limitUsage) {
  const u = usage == null ? "—" : String(usage);
  if (limitUsage != null && Number(limitUsage) > 0) {
    return `${u} / ${limitUsage}`;
  }
  return `${u} (хязгаар тодорхойгүй)`;
}

